-- Catalog cleanup from the owner's answers (2026-10-13)
-- * Clearer English names: GP = junction box, Chassis = LED profile chassis, TP = triple-pole MCB,
--   QL SE = surface light, QL SLENDR = cylinder light, supplier model codes = ceiling & wall lights
-- * One listing per size: repeats are hidden (the best-selling entry is kept); if the repeats had
--   different prices the kept listing becomes price on request
-- * No-name items and off-scope items (fire machine, testers, speaker, smoke alarm) are hidden
-- * O-1737-3 (SKU 11422) is the black lace cluster chandelier on offer: it takes the showroom
--   photo and the 40% offer, and the duplicate MCH-11 listing is hidden
-- Nothing is deleted; hidden products stay in the admin.
BEGIN;

CREATE TEMP TABLE catalog_cleanup (sku text PRIMARY KEY, name_en text, category_slug text, price numeric, active boolean, image_url text) ON COMMIT DROP;

UPDATE public.products p SET
  name_en = COALESCE(c.name_en, p.name_en),
  category_id = COALESCE((SELECT id FROM public.categories WHERE slug = c.category_slug), p.category_id),
  base_price = COALESCE(c.price, p.base_price),
  sale_price = CASE WHEN c.price IS NOT NULL THEN NULL ELSE p.sale_price END,
  is_active = COALESCE(c.active, p.is_active)
FROM catalog_cleanup c WHERE p.sku = c.sku;

UPDATE public.product_images pi SET url = c.image_url
FROM catalog_cleanup c JOIN public.products p ON p.sku = c.sku
WHERE pi.product_id = p.id AND pi.is_primary AND c.image_url IS NOT NULL
  AND pi.url LIKE 'https://images.unsplash.com/%';

-- Black lace cluster: real SKU carries the offer and the showroom photo; the duplicate goes
UPDATE public.products SET sale_price = 13.250, is_active = true WHERE sku = '11422' AND base_price = 22;
UPDATE public.product_images pi SET url = 'https://yubebbfsmlopmnluajgf.supabase.co/storage/v1/object/public/product-images/chandeliers/black-lace-cylinder-cluster.jpg'
FROM public.products p WHERE pi.product_id = p.id AND p.sku = '11422' AND pi.is_primary;
UPDATE public.products SET is_active = false WHERE sku = 'MCH-11';

COMMIT;
